// Inlines assets/illustrations/*.svg into the onboarding illustration module.
//
//   node scripts/inline-illustrations.mjs
//
// The SVGs are the source of truth; this file is generated from them.
import { readFileSync, writeFileSync } from 'fs';

const SLIDES = [
  ['welcome', 'WELCOME'],
  ['how-it-works', 'HOW_IT_WORKS'],
  ['your-data', 'YOUR_DATA'],
];

/**
 * Every colour an illustration may carry, by token name. `recolour-illustrations.mjs` maps the
 * unDraw palette onto exactly these, and anything else here is a build error rather than a colour
 * literal that slips into the app through a string the design-system guard cannot read into.
 */
const TOKENS = {
  '#1A1712': 'ink',
  '#2E2D33': 'raised',
  '#6E6C76': 'textTertiary',
  '#9A98A1': 'textSecondary',
  '#A6ADED': 'lavender',
  '#EE9080': 'coral',
  '#F1DD79': 'butter',
  '#F4F3F6': 'text',
};

const HEADER = `/**
 * Onboarding illustrations from unDraw (https://undraw.co), free to use without attribution.
 *
 * Inlined as template strings rather than imported as \`.svg\` files: that would need a Metro
 * transformer and a Jest mock, and would give the web export a separate asset to fetch. A string
 * renders the same on every platform and in the test environment.
 *
 * Every colour is interpolated from \`src/theme/tokens.ts\` rather than written out, so these
 * drawings cannot drift off the palette — and so the design system's one-file monopoly on colour
 * literals holds here too.
 *
 * Generated by scripts/inline-illustrations.mjs from assets/illustrations/*.svg — edit those, not
 * this file.
 */
import { colors } from '@/theme/tokens';
`;

/** Turns every hex in the SVG into a `${colors.x}` interpolation, and escapes the rest. */
const toTemplateLiteral = (svg) => {
  const escaped = svg.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');

  return escaped.replace(/#[0-9a-fA-F]{3,8}\b/g, (hex) => {
    const token = TOKENS[hex.toUpperCase()];

    if (token === undefined) {
      throw new Error(`${hex} is not a token — run scripts/recolour-illustrations.mjs first`);
    }

    return `\${colors.${token}}`;
  });
};

const body = SLIDES.map(([file, constant]) => {
  const svg = readFileSync(`assets/illustrations/${file}.svg`, 'utf8')
    .replace(/<\?xml[^>]*\?>/, '')
    .trim()
    .replace(/\s(width|height)="[^"]*"/, '')
    .replace(/\s(width|height)="[^"]*"/, '');

  return `export const ${constant}_ILLUSTRATION = \`${toTemplateLiteral(svg)}\`;`;
}).join('\n\n');

writeFileSync('src/features/onboarding/_illustrations/illustrations.ts', `${HEADER}\n${body}\n`);
console.log(`inlined ${SLIDES.length} illustrations`);
